        return 0.0, round(dev_hours * hourly_rate, 4)
    tokens = n_calls * tokens_per_call
    token_cost = tokens / 1e6 * price_per_mtok
    return round(token_cost, 4), round(token_cost + dev_hours * hourly_rate, 4)

